/*
 * School-age expansion activities.  This file is intentionally separate from
 * talent-catalog.js so the core catalog can be reviewed and merged in stages.
 * Every row is a complete activity; adaptations change the entry point while
 * keeping the same activity and evidence.
 */

const levels = ['start', 'start', 'start', 'practice', 'practice', 'practice', 'apply', 'apply'];

const commonAdaptations = (s) => s.adaptations || {
  start: `先看一个完成示例，再把“${s.title}”拆成三步；家长或同伴只示范第一步。`,
  practice: `独立完成“${s.title}”，增加一个真实限制，并请一位同伴按说明复做一处。`,
  apply: `把“${s.title}”换到学校或家庭的真实场景，保留原记录方式并解释一次取舍。`
};

const make = (directionId, age, index, s) => ({
  id: `expand_${age}_${directionId}_${s.slug}`,
  directionId,
  ageGroups: [age],
  level: levels[index],
  title: s.title,
  summary: s.summary,
  minutes: s.minutes,
  materials: s.materials,
  steps: s.steps,
  deliverable: s.deliverable,
  observe: s.observe,
  transfer: s.transfer,
  reflection: s.reflection,
  rubric: s.rubric,
  adaptations: commonAdaptations(s)
});

