      {slug:'paper-playground',title:'把纸箱变成可玩的小空间',summary:'用一个纸箱设计能容纳两种玩法的微型空间，观察别人怎样进入、拿取和收回。',minutes:45,materials:['纸箱','剪刀和胶带','积木或小玩具'],steps:['画出入口、放置区和两种玩法的平面图','制作可打开的原型，给边缘和承重点做安全检查','让同伴按图玩两分钟，记录他自然选择的入口和卡点'],deliverable:'纸箱原型、平面图、试玩观察和一项改版。',observe:['玩法差异来自空间或规则的具体变化','试玩者能安全取放并知道如何收回'],transfer:'把空间分区用于书桌整理、阅读角或雨天游戏。',reflection:['哪一处设计让别人开始玩？','怎样让收拾也成为设计的一部分？'],rubric:['原型可操作且有两种不同玩法','安全和收纳被纳入方案','依据试玩行为完成改版'],adaptations:{start:'使用预切纸箱和一张入口模板，孩子先完成一个能打开的空间。',practice:'加入一个尺寸限制，让同伴试玩并说出哪处需要改。',apply:'为真实班级休息角做低成本原型，和使用者共同确定收纳规则。'}},
      {slug:'quiet-corner',title:'设计一个安静角落的使用提示',summary:'观察家中或教室里需要安静的时段，设计让人愿意遵守且可以调整的提示和摆放。',minutes:35,materials:['现场平面图','纸卡和胶带','计时器'],steps:['记录声音来源、通行路线和使用者需要，不拍摄他人','做两种提示牌并选择放置位置，写出可暂停和例外规则','请两位使用者试走，记录他们是否知道该做什么'],deliverable:'两版提示牌、位置草图、试走记录和修订版。',observe:['提示说清行为与时间而非只写“请安静”','使用者知道遇到紧急或特殊情况怎么处理'],transfer:'把行为提示设计用于图书角、器材室或家庭共同空间。',reflection:['谁可能无法按这个提示行动？','怎样让规则不变成对人的责备？'],rubric:['提示具体、尊重且有例外','位置和版式支持现场理解','根据使用者反馈调整信息'],adaptations:{start:'由成人提供安静时段和规则，孩子只设计一个图标和一句行动提示。',practice:'做两个位置测试，比较远看和近看时的可读性。',apply:'在真实空间试用一周，收集执行困难并更新规则卡。'}},
      {slug:'reusable-wrap',title:'给午餐设计可重复使用的包裹',summary:'用现有材料为一件午餐物品设计可打开、可清洁、可重复使用的包裹。',minutes:45,materials:['旧布或纸张','胶带/绳子','要包的物品','水和抹布'],steps:['量出物品尺寸，列出防掉落、易打开和可清洁三个需求','做两个不同开合方式的样品，分别计时使用','让使用者带着走一小段再打开，记录损坏和不便处'],deliverable:'两个包裹样品、需求表、使用测试和选定方案。',observe:['样品确实保护物品且能在真实动作中打开','测试包含清洁或重复使用的限制'],transfer:'把需求权衡用于文具收纳、借物包装或旅行整理。',reflection:['哪个设计选择牺牲了什么？','“环保”还需要哪些实际证据？'],rubric:['需求与测试条件对应','至少一轮真实使用带来修改','能说明材料、耐用和清洁边界'],adaptations:{start:'成人帮量尺寸，孩子用一种材料完成包裹并测试开合。',practice:'自己选择两种开合方式，加入清洁测试并比较时间。',apply:'让同伴连续使用三次，记录耐用性并提出材料替代方案。'}},
      {slug:'map-for-small-hands',title:'为小朋友改画一张路线图',summary:'把从教室到图书馆或操场的路线画成低阅读负担、能看出安全边界的图。',minutes:40,materials:['现场地图或草图','纸和彩笔','一位低年级试读者'],steps:['走一遍路线，标出转弯、门、等待点和不应进入区域','画两版：图标版和文字版，保持比例大致一致','请试读者按图走到中途，询问哪里需要停下确认'],deliverable:'两版路线图、试走记录和面向目标读者的最终版。',observe:['地图把关键地标和安全边界画清','试读者能解释下一步而非只跟随成人'],transfer:'把路线图方法用于校园寻宝、社区导览或家庭出行。',reflection:['哪种信息对第一次走的人最重要？','地图怎样表达不确定或临时变化？'],rubric:['路线顺序和地标准确','图标、文字与安全提示匹配','依据目标使用者反馈改进'],adaptations:{start:'从两段短路线和三个图标开始，成人陪走并让孩子标转弯。',practice:'加入一个临时封路情景，让同伴按图找到替代路线。',apply:'为真实低年级活动制作可更新地图，标出日期和路线负责人。'}},
      {slug:'sound-instrument',title:'用日常物品做一件节奏小乐器',summary:'用安全、可回收物品制作能稳定发声的乐器，并为它设计两种使用场景。',minutes:40,materials:['纸杯、橡皮筋或豆子','胶带','录音设备'],steps:['比较三种材料的声音和固定方式，选择一组组合','制作能重复发声的样品，检查小零件和边缘安全','录下同一节奏的独奏和合奏，听后修改音量或握法'],deliverable:'安全乐器、两段录音和声音修改记录。',observe:['声音差异能指向材料或结构','合奏时能听见并照顾他人的音量'],transfer:'把材料试验用于故事配音、班级节奏游戏或环境声音采集。',reflection:['哪些声音适合独奏，哪些适合铺底？','如何设计方便清洁和保存的结构？'],rubric:['样品安全、可重复发声','设计选择有声音证据','根据合奏体验完成调整'],adaptations:{start:'使用成人准备的三种材料，孩子只完成一种稳固连接并模仿节奏。',practice:'自己改变一个结构参数，录音比较音高、音量或持续时间。',apply:'为班级故事做一段伴奏，和讲述者约定进出场信号后修订。'}},
      {slug:'fair-sharing-box',title:'设计一个公平分物的盒子',summary:'为糖果、贴纸或文具设计一个不靠争抢的分配装置或流程，记录使用者感受。',minutes:45,materials:['小盒子和纸片','标记笔','待分物品','两位使用者'],steps:['列出人数不同、有人迟到和物品数量不整齐三种情况','做一个盒子或抽签流程，标出顺序和补救办法','让两位使用者完成三轮分配，记录他们认为公平或不公平的地方'],deliverable:'分配原型、三种情境规则、测试记录和调整方案。',observe:['规则能处理数量不整齐与退出情况','使用者能复述程序并说出顾虑'],transfer:'把公平分配用于班级材料、游戏角色或家务机会。',reflection:['公平是每人一样还是需求不同？','谁负责处理例外？'],rubric:['规则具体、透明、可复做','测试覆盖不同情境并记录体验','调整回应具体顾虑而非只改外观'],adaptations:{start:'用两人等量分物和图卡流程，先练习按顺序取物。',practice:'加入三人和不整齐数量，比较补发、轮换两种方案。',apply:'在一次真实小组活动中试行，收集匿名反馈并发布修订规则。'}},
      {slug:'story-stage',title:'为故事做一个可移动的小舞台',summary:'用纸盒和背景片把故事地点做成能切换的舞台，测试观众是否看懂场景变化。',minutes:50,materials:['纸盒','彩纸和胶带','故事文本','手机相机'],steps:['选三处场景，画出必须出现的地点线索和人物位置','制作可移动背景和一个简单机关，确保手指可安全操作','请观众只看舞台和听旁白，记录他何时看懂场景转变'],deliverable:'可切换舞台、三场景草图、观看记录和一项改良。',observe:['场景变化有明确视觉线索而非依赖解释','机关不遮挡人物动作和旁白'],transfer:'把空间和叙事结合用于读书展示、科学模型或戏剧排练。',reflection:['哪个线索最帮助观众理解？','机关复杂度是否值得它带来的效果？'],rubric:['模型能安全切换且支持故事','观众理解有实际观察证据','依据观看记录简化或强化一处设计'],adaptations:{start:'先做一个固定背景和一张人物卡，成人帮助切出安全窗口。',practice:'增加两个可切换背景，邀请同伴指出场景变化的时间。',apply:'把舞台用于班级朗读，收集观众问题后提交可复用结构。'}},
      {slug:'rainy-day-kit',title:'设计一个雨天等待小工具包',summary:'为一次放学延迟或户外活动取消设计便携工具包，兼顾人数、清洁和不同玩法。',minutes:45,materials:['小收纳袋','纸牌或小玩具','清洁用品','参与者需求卡'],steps:['询问三位使用者在等待时想做什么和不想接触什么','搭配两种安静活动与一种合作活动，写清归还和清洁规则','模拟等待15分钟，记录无聊、争抢和收纳问题后调整'],deliverable:'工具包、活动规则卡、模拟记录和清洁收纳方案。',observe:['活动能让不同熟悉度的人加入或退出','物品清点和清洁步骤具体可执行'],transfer:'把工具包思路用于旅行、候诊或班级临时空档。',reflection:['谁可能因材料或规则被排除？','怎样让等待时间有选择而非被强迫参加？'],rubric:['内容适合场景且可携带','规则、清洁和归还清楚','根据模拟使用调整活动或物品'],adaptations:{start:'使用三种固定材料，孩子完成安静活动卡和归还清单。',practice:'让参与者自行选择活动，记录哪种规则减少争抢。',apply:'为真实活动准备工具包，试用后收集匿名意见并更新清单。'}}
