      {slug:'field-recording-ethics',title:'做一组有伦理边界的环境录音',summary:'记录校园或社区环境声，避免录入可识别谈话和私人空间，并写出发布说明。',minutes:60,materials:['录音设备','安全路线','录音日志','同意说明'],steps:['划定不录区域和停止信号，测试只收环境声的距离与方向','在三个时段录短片段并写地点、时间和可听元素','请同伴检查是否含可识别内容，剪辑后附来源、许可和撤回方式'],deliverable:'三段环境声、录音日志、伦理检查表和发布说明。',observe:['录音不包含可识别谈话或未经同意的个人声音','发布说明清楚地点精度与撤回入口'],transfer:'把伦理记录用于摄影、采访、校园新闻或自然观察。',reflection:['谁可能被无意录入？','作品效果和隐私边界冲突时怎么取舍？'],rubric:['采集范围安全且日志完整','剪辑和发布尊重同意与隐私','能说明限制、来源与撤回方式'],adaptations:{start:'只录室外自然声和钟声，成人协助设置不录区域。',practice:'在不同距离测试人声风险，建立剪辑检查清单。',apply:'发布到真实作品集前请场地管理者审核，并保留撤回流程。'}},
      {slug:'lyrics-source',title:'给一首歌做事实与记忆注释',summary:'把歌词意象、公开背景和自己的听感写成注释，不复制受版权保护的大段歌词。',minutes:55,materials:['合法可听歌曲','公开背景资料','注释模板'],steps:['只摘录必要的短词或用自己的话概括段落，标出来源','分别写作者/时代等可查事实、作品解释和个人听感','请同伴指出哪些句子把推测写成事实，修订并注明版本日期'],deliverable:'一页注释、来源表、听感反馈和修订说明。',observe:['引用克制且不泄露受版权保护内容','解释承认多种理解而非声称唯一答案'],transfer:'把来源与解释区分用于诗歌赏析、影评或文化研究。',reflection:['哪种解读需要更多证据？','个人记忆如何与作品背景并置？'],rubric:['来源和版本日期清楚','事实、解释、听感分层','依据同伴检查修订表达'],adaptations:{start:'用一首公共领域作品和两条背景资料，只写事实与一句听感。',practice:'加入一个不同解读，让同伴找出证据和推测边界。',apply:'为真实社团分享制作注释卡，控制引用并开放不同回应。'}},
      {slug:'beat-for-movement',title:'为一段集体动作做节拍方案',summary:'为热身、走位或非竞速活动设计三种速度和停止信号，测试不同熟悉度参与者。',minutes:60,materials:['节拍器或音频','动作流程','安全场地','反馈卡'],steps:['写出动作目标、停止信号、休息和替代动作','制作慢、中、快三版节拍，先由带领者试走','邀请不同熟悉度参与者选择版本，记录协调、舒适和误解后调整'],deliverable:'三版节拍音频/卡片、安全流程和参与反馈。',observe:['速度选择不变成排名或压力','参与者知道停止、休息和替代方式'],transfer:'把节拍调节用于运动带领、舞台走位或团体游戏。',reflection:['哪个信号最容易被忽略？','如何让节拍支持而非控制参与者？'],rubric:['节拍与动作目标对应','安全边界和选择清楚','真实试走带来修改'],adaptations:{start:'只做慢速四拍和停止信号，成人示范替代动作。',practice:'加入两种速度与休息点，邀请参与者选择并解释。',apply:'在真实活动试用，按匿名舒适度和完成情况调整。'}},
      {slug:'sound-accessibility',title:'为视频做声音可达性替代',summary:'给一段校园视频增加字幕、声音描述和音量提示，让不依赖单一听觉通道的观众也能理解。',minutes:70,materials:['短视频','字幕/剪辑工具','测试设备','两位测试者'],steps:['列出必须理解的语音、环境声和画面信息，不记录测试者身份','制作字幕、关键音效文字与音量版本，说明无法确定的声音','让两位测试者完成理解任务，按遗漏和负担修订一处'],deliverable:'可达性版本视频、文本稿、测试记录和未覆盖说明。',observe:['文本准确、同步并不把声音效果写成事实','测试关注理解任务而不是评价使用者'],transfer:'把替代通道用于线上课程、社团宣传或公共活动视频。',reflection:['哪些声音信息对剧情/任务真正必要？','可达性工作如何提前纳入制作而非事后补？'],rubric:['语音、环境声和画面信息有对应文本','版本能在测试设备上使用','依据真实任务反馈修订并说明限制'],adaptations:{start:'先给一段无对白短视频写三条关键音效描述。',practice:'加入对白字幕和音量控制，做手机与电脑测试。',apply:'为真实社团视频制作版本并请使用者审核理解。'}},
      {slug:'ensemble-arrangement',title:'为三人合作改编一段旋律',summary:'把短旋律拆成主线、节奏和低音/持续音，安排轮流练习、版本记录和反馈。',minutes:75,materials:['乐器或人声','旋律谱/录音','节拍器','版本表'],steps:['确认每人熟悉的音域或动作，选一段可完成的旋律','做两种分工和进入/退出信号，分别录下片段','让听众说出层次和冲突点，按反馈调整一处并记录版本'],deliverable:'两版编配、分工谱/卡、录音和反馈/版本日志。',observe:['分工让每人有可选择的参与方式','修改能具体对应层次、节拍或音量问题'],transfer:'把分工与版本管理用于乐队、视频制作或小组汇报。',reflection:['谁的声音容易被盖住？','什么时候简化比增加声部更好？'],rubric:['声部和进入信号清楚','合作安排尊重能力差异','听感反馈驱动版本改动'],adaptations:{start:'用拍手、哼唱和持续音三层，成人帮助保持拍子。',practice:'增加进入/退出信号并录两版比较。',apply:'为真实演出或视频提供可替换声部，按合作者反馈定稿。'}},
      {slug:'silence-composition',title:'为一段声音作品设计有意义的留白',summary:'用短旋律或环境声做两个版本，改变留白位置和长度，观察听众如何理解变化。',minutes:50,materials:['手机录音或乐器','节拍器','时间标记表','两位听众'],steps:['选一段不超过一分钟的声音，标出可能停下的转折点','制作连续版和有两处留白版，记录每处停顿时长','让听众写下期待、转折和结束的感受，依据反馈调整一处'],deliverable:'两版声音作品、时间标记和听众反馈/最终版。',observe:['停顿位置与结构或听感目标对应','作品不把听众的不同解释视为错误'],transfer:'把留白设计用于播客、朗读、舞台或界面提示音。',reflection:['留白改变了什么预期？','怎样判断停顿是表达还是空缺？'],rubric:['两个版本的差异可听且有记录','结构和听感反馈相互对应','根据听众反馈作出有理由的调整'],adaptations:{start:'用四拍节奏在中间停一拍，先听连续与停顿差别。',practice:'自己选择两处停顿并比较不同长度。',apply:'为真实音频或朗读做留白版本，邀请制作者确认。'}}
